/**
 * Configuration Manager
 * 配置管理模块
 */

const fs = require('fs');
const path = require('path');

/**
 * 默认配置
 */
const DEFAULT_CONFIG = {
  db: {
    type: 'better-sqlite3',
    path: './db/gitwork.db',
    host: 'localhost',
    port: 3306,
    pool: {
      min: 2,
      max: 10
    }
  },
  log: {
    level: 'INFO',
    file: './logs/app.log'
  },
  agent: {
    heartbeatInterval: 5 * 60 * 1000,
    syncInterval: 10 * 60 * 1000
  }
};

/**
 * 从环境变量加载配置
 */
function loadFromEnv() {
  const config = {};
  
  // 数据库配置
  if (process.env.DB_TYPE) config.db = { ...config.db, type: process.env.DB_TYPE };
  if (process.env.DB_PATH) config.db = { ...config.db, path: process.env.DB_PATH };
  if (process.env.DB_HOST) config.db = { ...config.db, host: process.env.DB_HOST };
  if (process.env.DB_PORT) config.db = { ...config.db, port: parseInt(process.env.DB_PORT) };
  
  // 日志配置
  if (process.env.LOG_LEVEL) config.log = { ...config.log, level: process.env.LOG_LEVEL };
  if (process.env.LOG_FILE) config.log = { ...config.log, file: process.env.LOG_FILE };
  
  // Agent 配置
  if (process.env.HEARTBEAT_INTERVAL) config.agent = { ...config.agent, heartbeatInterval: parseInt(process.env.HEARTBEAT_INTERVAL) };
  if (process.env.SYNC_INTERVAL) config.agent = { ...config.agent, syncInterval: parseInt(process.env.SYNC_INTERVAL) };
  
  return config;
}

/**
 * 从自定义配置文件加载配置
 */
function loadFromCustomConfig(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }
  try {
    const fileConfig = JSON.parse(fs.readFileSync(filePath, 'utf8'));
    return fileConfig;
  } catch (error) {
    console.warn('Failed to load custom config:', error.message);
    return {};
  }
}

/**
 * 合并配置
 */
function mergeConfigs(...configs) {
  return configs.reduce((acc, config) => ({ ...acc, ...config }), {});
}

class Config {
    constructor() {
        this.config = {};
        this.loaded = false;
    }

    /**
     * 加载配置
     */
    async load() {
        if (this.loaded) return;
        
        // 从环境变量加载
        this.config.github = {
            token: process.env.GITHUB_TOKEN || '',
            owner: process.env.GITHUB_OWNER || 'default-owner'
        };

        this.config.agents = {
            dev_count: parseInt(process.env.DEV_AGENT_COUNT) || 2,
            test_count: parseInt(process.env.TEST_AGENT_COUNT) || 1,
            review_count: parseInt(process.env.REVIEW_AGENT_COUNT) || 1
        };

        this.config.logging = {
            level: process.env.LOG_LEVEL || 'info',
            file: process.env.LOG_FILE || 'github-collab.log'
        };

        // 默认 QQ 配置（不依赖数据库）
        this.config.qq = {
            enabled: process.env.QQ_ENABLED === 'true',
            token: process.env.QQ_TOKEN || '',
            defaultTarget: process.env.QQ_TARGET || '',
            agentAddresses: {},
            dbConfigured: false
        };

        // 从配置文件加载（如果存在）
        const configPath = path.join(__dirname, '.github-collab-config.json');
        if (fs.existsSync(configPath)) {
            try {
                const fileConfig = JSON.parse(fs.readFileSync(configPath, 'utf8'));
                this.config = { ...this.config, ...fileConfig };
            } catch (error) {
                console.warn('Failed to load config file:', error.message);
            }
        }

        this.loaded = true;
        console.log('[Config] Configuration loaded');
    }

    /**
     * 获取配置
     * @param {string} key - 配置键（支持点号分隔）
     * @returns {any} - 配置值
     */
    get(key) {
        if (!this.loaded) {
            return this.config[key];
        }
        const keys = key.split('.');
        let value = this.config;
        for (const k of keys) {
            value = value?.[k];
        }
        return value;
    }

    /**
     * 获取全部配置
     * @returns {object} - 全部配置
     */
    getAll() {
        return this.config;
    }

    /**
     * 设置配置
     * @param {string} key - 配置键
     * @param {any} value - 配置值
     */
    set(key, value) {
        const keys = key.split('.');
        let config = this.config;
        for (let i = 0; i < keys.length - 1; i++) {
            if (!config[keys[i]]) {
                config[keys[i]] = {};
            }
            config = config[keys[i]];
        }
        config[keys[keys.length - 1]] = value;
    }

    /**
     * 保存配置到文件
     */
    save() {
        const configPath = path.join(__dirname, '.github-collab-config.json');
        fs.writeFileSync(configPath, JSON.stringify(this.config, null, 2));
        console.log('[Config] Configuration saved to:', configPath);
    }

    /**
     * 重新加载配置
     */
    reload() {
        this.loaded = false;
        this.load();
    }
}

// 创建单例
const configInstance = new Config();

/**
 * 获取配置实例
 * @returns {Config} - 配置实例
 */
function getConfig() {
    return configInstance;
}

/**
 * 初始化配置（异步）
 * @returns {Promise<void>}
 */
async function initConfig() {
    await configInstance.load();
}

module.exports = { 
  Config, 
  getConfig, 
  initConfig,
  DEFAULT_CONFIG,
  loadFromEnv,
  loadFromCustomConfig,
  mergeConfigs
};